from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'artifacts/replica/windows-download';OUT.mkdir(parents=True,exist_ok=True)
SOURCE=ROOT/'docs/replica/source'
for ext in ('js','css'):
    data=(SOURCE/f'original.{ext}').read_bytes();(OUT/f'home-pageintegrationtrial-original.{ext}').write_bytes(data)
cases=[dict(id=f'trial-{lang}-{width}-{state}',screen='trial',english=lang=='en',width=width,height=900,state=state) for lang in ('ko','en') for width in (960,1180,1280,1440) for state in ('default','consent','ready')]
