inner='''<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="home-pageintegrationtrial-original.css"><div id="app"></div><div id="dialog-host"></div><div id="toast-host" role="status" aria-live="polite"></div><div id="announcer" class="sr" role="status" aria-live="polite"></div><input id="file-open" hidden type="file"><script src="home-pageintegrationtrial-original.js"></script><script>
const params=new URLSearchParams(location.search);lang=params.get('lang')||'ko';state.screen='trial';state.trial.consent=params.get('state')!=='default';state.trial.ready=params.get('state')==='ready';render();
const box=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};
const text=e=>e?.textContent.trim()||'';
function button(e){return{action:e?.dataset.action,label:text(e),enabled:!e.disabled,box:box(e)}}
function read(){return{id:params.get('id'),viewport:{width:innerWidth,height:innerHeight},topbar:box(document.querySelector('.topbar')),sidebar:box(document.querySelector('.rail')),strip:box(document.querySelector('.sample-strip')),content:box(document.querySelector('.content')),page:box(document.querySelector('.page')),footer:box(document.querySelector('.footer')),hint:{text:text(document.querySelector('.footer-hint')),box:box(document.querySelector('.footer-hint'))},back:button(document.querySelector('.footer>.btn')),primary:button(document.querySelector('.footer .primary'))}}
const boundaryNames=['bom-valid','nel-valid','bom-host','nel-host'];
const names=params.get('validation')==='1'?boundaryNames:['disabled','inputs-priority','invalid-empty','host-empty','db-empty','same-source','same-target','exact-whitespace','success','stale-success','edit-reset','consent-reset','return-reopen','language'];
function seed(name){state=initial();state.screen='trial';state.trial.consent=name!=='disabled';state.error='';if(name==='inputs-priority'){state.trial.validInput=' ';state.trial.host='';}if(name==='invalid-empty')state.trial.invalidInput=' ';if(name==='host-empty')state.trial.host=' ';if(name==='db-empty')state.trial.db=' ';if(name==='same-source'||name==='same-target'){let side=name==='same-source'?state.source:state.target;state.trial.host=side.host;state.trial.db=side.db;}if(name==='exact-whitespace'){state.trial.host=' '+state.source.host;state.trial.db=state.source.db;}if(['stale-success','edit-reset','return-reopen','language'].includes(name))state.error='owned-stale-error';if(['edit-reset','consent-reset','return-reopen','language'].includes(name))state.trial.ready=true;if(name==='bom-valid')state.trial.validInput='\\uFEFF';if(name==='nel-valid')state.trial.validInput='\\u0085';if(name==='bom-host')state.trial.host='\\uFEFF';if(name==='nel-host')state.trial.host='\\u0085';render(true);}
function stateRead(id,extra={}){let p=document.querySelector('.footer .primary');return{id,screen:state.screen,english:lang==='en',host:state.trial.host,database:state.trial.db,validInput:state.trial.validInput,invalidInput:state.trial.invalidInput,consent:state.trial.consent,ready:state.trial.ready,error:state.error,primary:p?{action:p.dataset.action,label:text(p),enabled:!p.disabled}:null,announcement:document.getElementById('announcer').textContent,focus:document.activeElement?.dataset.action||document.activeElement?.id||document.activeElement?.dataset.field||document.activeElement?.dataset.flag||'BODY',...extra}}
async function flow(name){seed(name);const id=(lang==='en'?'en':'ko')+'-'+name;let extra={};if(name==='edit-reset'){const page=document.querySelector('.page'),field=document.querySelector('[data-field="trial.validInput"]'),primary=document.querySelector('.footer .primary');field.focus();field.value='owned-parent-value';field.dispatchEvent(new Event('input',{bubbles:true}));extra={pageRetained:page===document.querySelector('.page'),editorRetained:field===document.querySelector('[data-field="trial.validInput"]'),primaryRetained:primary===document.querySelector('.footer .primary'),readyNotice:!!document.querySelector('.notice.ok')};}else if(name==='consent-reset'){const c=document.querySelector('[data-flag="trial.consent"]');c.focus();c.checked=false;c.dispatchEvent(new Event('change',{bubbles:true}));}else if(name==='return-reopen'){document.querySelector('.footer .primary').focus();document.querySelector('.footer .primary').click();extra={returned:state.screen==='select',returnError:state.error,returnOffset:document.getElementById('main').scrollTop};go('trial');extra.reopenOffset=document.getElementById('main').scrollTop;}else if(name==='language'){document.querySelector('[data-action="language"]').focus();document.querySelector('[data-action="language"]').click();}else{document.querySelector('.footer .primary').focus();document.querySelector('.footer .primary').click();if(state.trial.ready)extra.toast=text(document.querySelector('.toast'));}return stateRead(id,extra)}
async function flows(){let rows=[];for(const l of ['ko','en'])for(const n of names){lang=l;rows.push(await flow(n));}return rows;}
</script>'''
(OUT/'home-pageintegrationtrial-inner.html').write_text(inner)
frames=''.join(f'<iframe width="{c["width"]}" height="900" src="home-pageintegrationtrial-inner.html?id={c["id"]}&lang={"en" if c["english"] else "ko"}&state={c["state"]}" style="border:0;position:absolute;left:0;top:50px;visibility:hidden"></iframe>' for c in cases)
outer='''<!doctype html><meta charset="utf-8"><title>Trial application parent measurement · home</title><p id="state">Measuring</p>FRAMES<script>
async function record(){let fs=[...document.querySelectorAll('iframe')];for(let f of fs){if(f.contentDocument.readyState!=='complete')await new Promise(r=>f.onload=r);await f.contentDocument.fonts.ready;await Promise.all(f.contentDocument.getAnimations().filter(a=>a.effect.getTiming().iterations!==Infinity).map(a=>a.finished.catch(()=>{})));}let rows=fs.map(f=>f.contentWindow.read());let flows=await fs[0].contentWindow.flows();let os=/Windows/.test(navigator.userAgent)?'windows':'mac';let r=await fetch('/evidence/home-pageintegrationtrial-'+os+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recording:new URLSearchParams(location.search).get('recording'),dpr:devicePixelRatio,rows,flows,scope:'Synthetic original handler oracle; actual OS input separate'})});if(!r.ok)throw Error('Record failed');document.getElementById('state').textContent='Recorded parent24/flow28';}window.onload=record;
</script>'''.replace('FRAMES',frames)
