input_script=r'''<style>.parent-probe-tools{position:fixed;top:60px;right:2px;z-index:99999;background:#202125;color:white;font:11px system-ui}.parent-probe-tools button{font:11px system-ui}</style><div class="parent-probe-tools"><button id="parent-probe-next">Setup next parent case</button><button id="parent-probe-scroll">Setup editor scroll</button><button id="parent-probe-consent-scroll">Setup consent scroll</button><button id="parent-probe-reopen">Setup API reopen</button><span id="parent-probe-status"></span></div><script>
let caseIndex=-1,revision=0,snapshot=0,posting=false,seedPage=null,seedEditor=null,seedPrimary=null,trace=[];
const expectedOs=/Windows/.test(navigator.userAgent)?'windows':'mac';
function next(){if(caseIndex>=names.length*2-1)return;caseIndex++;revision++;lang=caseIndex>=names.length?'en':'ko';seed(names[caseIndex%names.length]);seedPage=document.querySelector('.page');seedEditor=document.querySelector('[data-field="trial.validInput"]');seedPrimary=document.querySelector('.footer .primary');if(names[caseIndex%names.length]==='edit-reset')seedEditor.scrollIntoView({block:'center',behavior:'instant'});if(names[caseIndex%names.length]==='consent-reset')document.querySelector('[data-flag="trial.consent"]').scrollIntoView({block:'center',behavior:'instant'});trace=[];document.getElementById('parent-probe-status').textContent=(lang+'-'+names[caseIndex%names.length]);}
document.getElementById('parent-probe-next').onclick=next;
document.getElementById('parent-probe-scroll').onclick=()=>document.querySelector('[data-field="trial.validInput"]')?.scrollIntoView({block:'center',behavior:'instant'});
document.getElementById('parent-probe-consent-scroll').onclick=()=>document.querySelector('[data-flag="trial.consent"]')?.scrollIntoView({block:'center',behavior:'instant'});
document.getElementById('parent-probe-reopen').onclick=()=>go('trial');
document.addEventListener('pointerdown',e=>trace.push({kind:'down',revision,trusted:e.isTrusted,target:e.target.closest('[data-action],[data-field],[data-flag]')?.outerHTML.slice(0,240)||e.target.tagName,x:e.clientX,y:e.clientY}));
document.addEventListener('pointerup',e=>trace.push({kind:'up',revision,trusted:e.isTrusted,target:e.target.closest('[data-action],[data-field],[data-flag]')?.outerHTML.slice(0,240)||e.target.tagName}));
document.addEventListener('keydown',e=>trace.push({kind:'key',revision,trusted:e.isTrusted,key:e.key}));
async function passive(){if(posting||caseIndex<0)return;posting=true;try{let id=(caseIndex<names.length?'ko-':'en-')+names[caseIndex%names.length];let controls=[...document.querySelectorAll('.footer button,[data-field^="trial."],[data-flag="trial.consent"],[data-action="language"]')].map(e=>({id:e.id,action:e.dataset.action,field:e.dataset.field,flag:e.dataset.flag,box:box(e),enabled:!e.disabled,visible:!!e.getClientRects().length,focused:e===document.activeElement}));let data={snapshot:++snapshot,revision,index:caseIndex,caseId:id,state:stateRead(id),rawFocus:{id:document.activeElement?.id||'',tag:document.activeElement?.tagName,action:document.activeElement?.dataset.action,field:document.activeElement?.dataset.field,flag:document.activeElement?.dataset.flag},offset:document.getElementById('main').scrollTop,documentOffset:{x:document.scrollingElement.scrollLeft,y:document.scrollingElement.scrollTop},controls,pageRetained:seedPage===document.querySelector('.page'),editorRetained:seedEditor===document.querySelector('[data-field="trial.validInput"]'),primaryRetained:seedPrimary===document.querySelector('.footer .primary'),readyNotice:!!document.querySelector('.notice.ok'),trace,dpr:devicePixelRatio,scope:'Actual input observer; external utilities are setup-only'};await fetch('/evidence/home-pageintegrationtrial-'+expectedOs+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});}finally{posting=false;}}
next();setInterval(passive,100);
</script>'''
(OUT/'home-pageintegrationtrial-input.html').write_text(inner.replace('<meta charset="utf-8">','<meta charset="utf-8"><title>Trial application parent input · home</title>',1)+input_script)
